# PTX source for max‑reduction over a chosen dimension (dim=1) on fp16 tensors.
# The kernel computes: out[b, d2] = max_{d1} in[b, d1, d2]
# All pointers are to half‑precision (fp16) data.

PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry max_reduce_dim1(
    .param .u64   in_ptr,          // input tensor pointer (fp16)
    .param .u64   out_ptr,         // output tensor pointer (fp16)
    .param .u32   batch_size,      // B
    .param .u32   dim1,            // D1 (reduction dimension)
    .param .u32   dim2             // D2
)
{
    // ------------------------------------------------------------------
    // Load kernel parameters
    // ------------------------------------------------------------------
    .reg .u64   %in, %out;
    .reg .u32   %B, %D1, %D2;
    ld.param.u64    %in, [in_ptr];
    ld.param.u64    %out, [out_ptr];
    ld.param.u32    %B, [batch_size];
    ld.param.u32    %D1, [dim1];
    ld.param.u32    %D2, [dim2];

    // ------------------------------------------------------------------
    // Built‑in thread / block indices
    // ------------------------------------------------------------------
    .reg .u32   %tid, %bid_x, %bid_y, %ntid;
    mov.u32     %tid, %tid.x;          // thread index within block
    mov.u32     %ntid, %ntid.x;        // blockDim.x
    mov.u32     %bid_x, %ctaid.x;      // batch index
    mov.u32     %bid_y, %ctaid.y;      // dim2 index

    // ------------------------------------------------------------------
    // Bounds check (in case grid is larger than needed)
    // ------------------------------------------------------------------
    setp.ge.u32 %p1, %bid_x, %B;
    @%p1 bra    DONE;
    setp.ge.u32 %p2, %bid_y, %D2;
    @%p2 bra    DONE;

    // ------------------------------------------------------------------
    // Compute base offset (in elements) for this (b, d2) pair.
    // Layout: [B][D1][D2] row‑major.
    // offset = ((b * D1) * D2) + d2
    // ------------------------------------------------------------------
    .reg .u64   %base_idx, %tmp;
    cvt.u64.u32 %tmp, %bid_x;          // b
    mul.lo.u64  %tmp, %tmp, %D1;       // b * D1
    cvt.u64.u32 %base_idx, %tmp;
    mul.lo.u64  %base_idx, %base_idx, %D2; // (b*D1)*D2
    cvt.u64.u32 %tmp, %bid_y;          // d2
    add.u64     %base_idx, %base_idx, %tmp; // final element index

    // ------------------------------------------------------------------
    // Each thread walks the reduction dimension with stride = blockDim.x
    // ------------------------------------------------------------------
    .reg .f16   %val, %thread_max;
    .reg .u32   %i;
    // Initialise thread_max to most negative half value (-65504.0)
    mov.f16     %thread_max, -65504.0;

    // Loop: for (i = tid; i < D1; i += blockDim.x)
    mov.u32     %i, %tid;
LOOP:
    setp.ge.u32 %p3, %i, %D1;
    @%p3 bra    REDUCE;               // exit loop when i >= D1

    // element index = base_idx + i * D2
    .reg .u64   %elem_idx, %offset_bytes;
    cvt.u64.u32 %tmp, %i;
    mul.lo.u64  %tmp, %tmp, %D2;       // i * D2
    add.u64     %elem_idx, %base_idx, %tmp;

    // convert element index to byte address (half = 2 bytes)
    shl.b64     %offset_bytes, %elem_idx, 1;
    add.u64     %offset_bytes, %in, %offset_bytes;
    ld.global.f16 %val, [%offset_bytes];

    // thread_max = max(thread_max, val)
    max.f16     %thread_max, %thread_max, %val;

    // i += blockDim.x
    add.u32     %i, %i, %ntid;
    bra         LOOP;

REDUCE:
    // ------------------------------------------------------------------
    // Store per‑thread max into shared memory for intra‑block reduction
    // ------------------------------------------------------------------
    .shared .align 2 .b8 sdata[256*2];   // max 256 threads per block
    .reg .u64   %s_ptr;
    cvt.u64.u32 %s_ptr, %tid;
    shl.b64     %s_ptr, %s_ptr, 1;       // byte offset = tid * 2
    add.u64     %s_ptr, sdata, %s_ptr;
    st.shared.f16 [%s_ptr], %thread_max;

    bar.sync    0;

    // ------------------------------------------------------------------
    // Reduce in shared memory (binary tree reduction)
    // ------------------------------------------------------------------
    .reg .u32   %stride;
    mov.u32     %stride, %ntid;
REDUCTION_LOOP:
    shr.u32     %stride, %stride, 1;
    setp.eq.u32 %p4, %stride, 0;
    @%p4 bra    FINAL_WRITE;

    setp.ge.u32 %p5, %tid, %stride;
    @%p5 bra    SKIP_REDUCE;

    // load my value and partner's value
    .reg .f16   %a, %b;
    ld.shared.f16 %a, [%s_ptr];
    .reg .u64   %partner_ptr;
    cvt.u64.u32 %partner_ptr, %tid;
    add.u32     %partner_ptr, %partner_ptr, %stride;
    shl.b64     %partner_ptr, %partner_ptr, 1;
    add.u64     %partner_ptr, sdata, %partner_ptr;
    ld.shared.f16 %b, [%partner_ptr];
    max.f16     %a, %a, %b;
    st.shared.f16 [%s_ptr], %a;

SKIP_REDUCE:
    bar.sync    0;
    bra         REDUCTION_LOOP;

FINAL_WRITE:
    // Thread 0 writes the final max to global output
    setp.ne.u32 %p6, %tid, 0;
    @%p6 bra    DONE;

    // Load reduced max from shared[0]
    ld.shared.f16 %val, [sdata];

    // Compute output byte address: out_idx = b * D2 + d2
    .reg .u64   %out_idx, %out_bytes;
    cvt.u64.u32 %out_idx, %bid_x;
    mul.lo.u64  %out_idx, %out_idx, %D2;
    cvt.u64.u32 %tmp, %bid_y;
    add.u64     %out_idx, %out_idx, %tmp;
    shl.b64     %out_bytes, %out_idx, 1;
    add.u64     %out_bytes, %out, %out_bytes;
    st.global.f16 [%out_bytes], %val;

DONE:
    ret;
}
"""

# ----------------------------------------------------------------------
# Python wrapper that loads and launches the PTX kernel.
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self, dim: int = 1):
        # The reference implementation only reduces over dim=1.
        # We keep the argument for API compatibility.
        self.dim = dim
        # Load PTX module (ptx_harness provides ptx_load)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        """
        x : torch.Tensor (float16) of shape (B, D1, D2)
        Returns torch.Tensor (float16) of shape (B, D2)
        """
        B, D1, D2 = x.shape
        out = torch.empty((B, D2), dtype=torch.float16, device=x.device)

        # Prepare launch configuration
        block = (256, 1, 1)                 # 256 threads per block
        grid = (B, D2, 1)                   # one block per output element

        # Arguments must be passed as a list of pointers/ints
        args = [
            x.data_ptr(),                  # input pointer
            out.data_ptr(),                # output pointer
            B,                             # batch size
            D1,                            # reduction dimension length
            D2                             # remaining dimension length
        ]

        # Launch kernel (ptx_harness provides ptx_launch)
        ptx_launch(self.module, "max_reduce_dim1", grid, block, args)

        return out
